+static void insertion_sort(uint32_t* a, size_t lo, size_t hi) {
+    for (size_t i = lo + 1; i < hi; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > lo && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
+}
+
+static void counting_sort(uint32_t* a, uint32_t* tmp, size_t n, int shift) {
+    uint32_t count[RADIX_SIZE] = {0};
+
+    // Count occurrences
+    for (size_t i = 0; i < n; ++i) {
+        int digit = (a[i] >> shift) & (RADIX_SIZE - 1);
+        count[digit]++;
+    }
+
+    // Convert to offsets
+    uint32_t offset = 0;
+    for (int i = 0; i < RADIX_SIZE; ++i) {
+        uint32_t old_offset = offset;
+        offset += count[i];
+        count[i] = old_offset;
+    }
+
+    // Distribute elements
+    for (size_t i = 0; i < n; ++i) {
+        int digit = (a[i] >> shift) & (RADIX_SIZE - 1);
+        tmp[count[digit]] = a[i];
+        count[digit]++;
+    }
+
+    // Copy back
+    for (size_t i = 0; i < n; ++i) {
+        a[i] = tmp[i];
+    }
+}
+
+static void radix_sort(uint32_t* a, uint32_t* tmp, size_t n) {
+    if (n <= 1) return;
+
+    // For small arrays, use insertion sort
+    if (n < INSERTION_SORT_THRESHOLD) {
+        insertion_sort(a, 0, n);
+        return;
+    }
+
+    // Use 3 passes of 11-bit radix sort
+    for (int shift = 0; shift < 32; shift += RADIX_BITS) {
+        counting_sort(a, tmp, n, shift);
+    }
